-- AutoDL hosted H3 catalog deployment guard (read-only sample).
-- Canonical/idempotent writes are generated by:
--   scripts/configure-autodl-hosted-h3-catalog.ts --apply
-- Keeping the JSON construction in TypeScript prevents this SQL sample from
-- drifting away from the protocol hashes used by the activation gate.

do $$
declare
  v_ids constant text[] := array[
    'minimax-h3-autodl-hosted-lightx2v-v5',
    'minimax-h3-autodl-hosted-text',
    'minimax-h3-autodl-hosted-first-last',
    'minimax-h3-autodl-hosted-lightx2v-v5-15s',
    'minimax-h3-autodl-hosted-image-audio',
    'minimax-h3-autodl-hosted-image-audio-v2',
    'minimax-h3-autodl-hosted-image-audio-v2-15s'
  ];
  v_count integer;
begin
  select count(*) into v_count
  from public.video_models
  where id = any(v_ids);
  if v_count <> 7 then
    raise exception 'AUTODL_HOSTED_H3_CATALOG_CARDINALITY_INVALID:%', v_count;
  end if;

  select count(*) into v_count
  from public.video_models
  where id = any(v_ids)
    and provider = 'autodl_comfyui_workflow'
    and protocol_type = 'autodl_comfyui_workflow'
    and api_key = 'secret://autodl-comfyui'
    and is_active = false
    and is_hidden = true
    and api_protocol_config->>'schema' = 'autodl_hosted_h3_workflow_catalog.v1'
    and api_protocol_config#>>'{__model_activation_gate,schema}' = 'media_model_activation_gate.v1'
    and api_protocol_config->>'billing_unit' = 'output_second'
    and api_protocol_config->>'persist_result_immediately' = 'true'
    and api_protocol_config->>'supports_remote_cancel' = 'false'
    and length(coalesce(api_protocol_config->>'official_contract_sha256', '')) = 64;
  if v_count <> 7 then
    raise exception 'AUTODL_HOSTED_H3_CATALOG_SAFETY_GATE_INVALID:%', v_count;
  end if;

  if not exists (
    select 1 from public.video_models
    where id = 'minimax-h3-autodl-hosted-lightx2v-v5'
      and model_name = 'minimax_h3_lightx2v_v5'
      and requires_image = true
      and api_protocol_config->>'workflow_input_mode' = 'multi_image'
      and api_protocol_config->>'required_reference_images' = '1'
      and api_protocol_config->>'max_reference_images' = '9'
      and api_protocol_config#>>'{resolution_prices,1080p}' = '0.1'
  ) then
    raise exception 'AUTODL_HOSTED_H3_MULTI_IMAGE_CONTRACT_INVALID';
  end if;

  if not exists (
    select 1 from public.video_models
    where id = 'minimax-h3-autodl-hosted-text'
      and model_name = 'minimax_h3_lightx2v_no_pic'
      and supports_image_input = false
      and requires_image = false
      and max_duration = 15
      and api_protocol_config->>'workflow_input_mode' = 'text'
      and api_protocol_config->>'supports_prompt' = 'true'
  ) then
    raise exception 'AUTODL_HOSTED_H3_TEXT_CONTRACT_INVALID';
  end if;

  if not exists (
    select 1 from public.video_models
    where id = 'minimax-h3-autodl-hosted-first-last'
      and api_protocol_config->>'requires_first_frame' = 'true'
      and api_protocol_config->>'requires_last_frame' = 'true'
  ) then
    raise exception 'AUTODL_HOSTED_H3_FIRST_LAST_CONTRACT_INVALID';
  end if;

  if not exists (
    select 1 from public.video_models
    where id = 'minimax-h3-autodl-hosted-image-audio'
      and api_protocol_config->>'duration_field' = 'audio_duration'
      and api_protocol_config->>'supports_prompt' = 'false'
      and api_protocol_config->>'required_reference_images' = '1'
      and api_protocol_config->>'required_reference_audios' = '1'
  ) then
    raise exception 'AUTODL_HOSTED_H3_LIPSYNC_CONTRACT_INVALID';
  end if;
end
$$;
